#include "stdlib/stats/base/dists/burr-type3/pdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/pow.h"

/**
* Evaluates the probability density function (PDF) for a Burr (type III) distribution with first shape parameter `alpha` and second shape parameter `beta`.
*
* @param x        input value
* @param alpha    first shape parameter
* @param beta     second shape parameter
* @return         evaluated PDF
*
* @example
* double y = stdlib_base_dists_burr_type3_pdf( 1.0, 1.0, 1.0 );
* // returns 0.25
*/
double stdlib_base_dists_burr_type3_pdf( const double x, const double alpha, const double beta ) {
	double out;
	if (
		stdlib_base_is_nan( x ) ||
		stdlib_base_is_nan( alpha ) ||
		stdlib_base_is_nan( beta ) ||
		alpha <= 0.0 ||
		beta <= 0.0 ||
		x <= 0.0
	) {
		return 0.0 / 0.0; // NaN
	}
	out = alpha * beta;
	out *= stdlib_base_pow( x, ( -alpha - 1.0 ) );
	out /= stdlib_base_pow( 1.0 + stdlib_base_pow( x, -alpha ), beta + 1.0 );
	return out;
}
